import { useEffect, useMemo, useRef, useState } from 'react';
import { Bell } from 'lucide-react';
import { useApp } from '../../contexts/AppContext';

// Header bell — notifications derived live from org data (no extra table).
// "Read" state is per browser, stored as a list of notification keys.
const SEEN_KEY = 'rfid_notif_seen';
const readSeen = () => { try { return new Set(JSON.parse(localStorage.getItem(SEEN_KEY)) || []); } catch { return new Set(); } };
const writeSeen = s => { try { localStorage.setItem(SEEN_KEY, JSON.stringify([...s].slice(-500))); } catch {} };

const DAY = 86400000;
const startOfToday = () => { const d = new Date(); d.setHours(0, 0, 0, 0); return d; };

export default function NotificationBell({ onNavigate }) {
  const { assets = [], checkouts = [], requests = [], deliveries = [] } = useApp();
  const [open, setOpen] = useState(false);
  const [seen, setSeen] = useState(readSeen);
  const ref = useRef(null);

  useEffect(() => {
    if (!open) return;
    const close = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, [open]);

  const items = useMemo(() => {
    const today = startOfToday(), out = [];
    assets.forEach(a => {
      if (!a.next_maintenance_date || a.status === 'Decommissioned') return;
      const days = Math.round((new Date(a.next_maintenance_date) - today) / DAY);
      if (days < 0) out.push({ key: `mo_${a.id}_${a.next_maintenance_date}`, sev: 3, icon: '🔧', color: '#e05757',
        title: `Maintenance overdue — ${a.name}`, sub: `${-days} day${days === -1 ? '' : 's'} overdue · ${a.currentFacilityName || '—'}`, page: 'assets', sort: days });
      else if (days <= 7) out.push({ key: `md_${a.id}_${a.next_maintenance_date}`, sev: 2, icon: '🗓', color: '#f5a623',
        title: `Maintenance due — ${a.name}`, sub: days === 0 ? 'Due today' : `Due in ${days} day${days === 1 ? '' : 's'}`, page: 'assets', sort: days });
    });
    checkouts.forEach(c => {
      if (c.status !== 'Out' || !c.dueDate || new Date(c.dueDate) >= today) return;
      const days = Math.round((today - new Date(c.dueDate)) / DAY);
      out.push({ key: `co_${c.id}`, sev: 3, icon: '⏳', color: '#e05757',
        title: `Checkout overdue — ${c.assetName || 'asset'}`, sub: `${c.checkedOutTo || '—'} · ${days} day${days === 1 ? '' : 's'} late`, page: 'checkout', sort: -days });
    });
    requests.filter(r => r.status === 'Pending').forEach(r => out.push({ key: `rq_${r.id}`, sev: 1, icon: '📋', color: '#5b9cf6',
      title: `Request pending — ${r.assetName || 'asset'}`, sub: r.requestedBy ? `By ${r.requestedBy}` : 'Awaiting approval', page: 'requests', sort: 0 }));
    deliveries.filter(d => d.status === 'Pending').forEach(d => out.push({ key: `dl_${d.id}`, sev: 1, icon: '🚚', color: '#b89de8',
      title: 'Delivery pending', sub: `${d.fromFacilityName || d.from_facility_name || '—'} → ${d.toFacilityName || d.to_facility_name || '—'}`, page: 'deliveries', sort: 0 }));
    return out.sort((a, b) => b.sev - a.sev || a.sort - b.sort);
  }, [assets, checkouts, requests, deliveries]);

  const unread = items.filter(i => !seen.has(i.key)).length;
  const markAll = () => { const s = new Set([...seen, ...items.map(i => i.key)]); setSeen(s); writeSeen(s); };
  const go = it => { const s = new Set(seen).add(it.key); setSeen(s); writeSeen(s); setOpen(false); onNavigate?.(it.page); };
  const mobile = typeof window !== 'undefined' && window.innerWidth < 768;

  return (
    <div ref={ref} style={{ position: 'relative', flexShrink: 0 }}>
      <button onClick={() => setOpen(o => !o)} title="Notifications"
        style={{ position: 'relative', background: 'none', border: '1px solid var(--border)', borderRadius: 7, color: unread ? 'var(--text)' : 'var(--text-3)',
                 cursor: 'pointer', padding: '5px 10px', display: 'inline-flex', alignItems: 'center' }}>
        <Bell size={14} />
        {unread > 0 && (
          <span style={{ position: 'absolute', top: -6, right: -6, minWidth: 17, height: 17, padding: '0 4px', borderRadius: 9, background: '#e05757',
                         color: '#fff', fontSize: 10, fontWeight: 700, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            {unread > 99 ? '99+' : unread}
          </span>
        )}
      </button>

      {open && (
        <div style={{ position: mobile ? 'fixed' : 'absolute', top: mobile ? 62 : 40, right: mobile ? 12 : 0, left: mobile ? 12 : 'auto',
                      width: mobile ? 'auto' : 360, background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 12,
                      boxShadow: '0 12px 40px rgba(0,0,0,.35)', zIndex: 9500, overflow: 'hidden' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 14px', borderBottom: '1px solid var(--border)' }}>
            <div style={{ fontWeight: 700, fontSize: 14, color: 'var(--text)' }}>Notifications {items.length > 0 && <span style={{ color: 'var(--text-dim)', fontWeight: 400, fontSize: 12 }}>({items.length})</span>}</div>
            {unread > 0 && <button onClick={markAll} style={{ background: 'none', border: 'none', color: 'var(--accent)', fontSize: 12, cursor: 'pointer' }}>Mark all read</button>}
          </div>
          <div style={{ maxHeight: 400, overflowY: 'auto' }}>
            {items.length === 0 && <div style={{ padding: '28px 14px', textAlign: 'center', color: 'var(--text-dim)', fontSize: 13 }}>✓ You're all caught up</div>}
            {items.slice(0, 100).map(it => {
              const isNew = !seen.has(it.key);
              return (
                <div key={it.key} className="row" onClick={() => go(it)}
                  style={{ display: 'flex', gap: 10, padding: '10px 14px', borderBottom: '1px solid var(--border)', cursor: 'pointer',
                           background: isNew ? 'color-mix(in srgb, var(--accent) 6%, transparent)' : 'transparent' }}>
                  <div style={{ width: 30, height: 30, borderRadius: 8, flexShrink: 0, display: 'flex', alignItems: 'center', justifyContent: 'center',
                                background: `${it.color}20`, fontSize: 14 }}>{it.icon}</div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 12.5, fontWeight: isNew ? 700 : 500, color: 'var(--text)', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{it.title}</div>
                    <div style={{ fontSize: 11, color: it.sev === 3 ? it.color : 'var(--text-dim)', marginTop: 2 }}>{it.sub}</div>
                  </div>
                  {isNew && <span style={{ width: 7, height: 7, borderRadius: 4, background: 'var(--accent)', marginTop: 6, flexShrink: 0 }} />}
                </div>
              );
            })}
            {items.length > 100 && <div style={{ padding: 10, textAlign: 'center', fontSize: 11, color: 'var(--text-dim)' }}>Showing 100 of {items.length}</div>}
          </div>
        </div>
      )}
    </div>
  );
}
